import os
import glob
import csv
import json

def inspect_csvs():
    print("=================== CSV INVENTORY ===================")
    for p in sorted(glob.glob("dataset/*.csv")):
        with open(p, "r", encoding="utf-8", errors="replace") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            rows = list(reader)
        print(f"File: {p}")
        print(f"  Rows: {len(rows)} | Cols: {len(header) if header else 0}")
        print(f"  Header: {header}")
        if rows:
            print(f"  Sample row 1: {rows[0]}")
            if len(rows) > 1:
                print(f"  Sample row 2: {rows[1]}")
        print()

def inspect_evidence():
    print("=================== EVIDENCE INVENTORY ===================")
    for root, dirs, files in os.walk("dataset/evidence"):
        if files:
            exts = {}
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                exts[ext] = exts.get(ext, 0) + 1
            print(f"{root}: {len(files)} files, types: {exts}")

if __name__ == "__main__":
    inspect_csvs()
    inspect_evidence()

import csv
import json

def analyze():
    print("=== DELETION RULES ===")
    with open("dataset/deletion_rules.csv", "r", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            print(dict(row))

    print("\n=== SAMPLE OUTPUT ANALYSIS ===")
    with open("dataset/sample_output.csv", "r", encoding="utf-8") as f:
        samples = list(csv.DictReader(f))

    status_counts = {}
    for s in samples:
        status_counts[s["deletion_status"]] = status_counts.get(s["deletion_status"], 0) + 1
    print("Status counts:", status_counts)

    for s in samples:
        steps = json.loads(s["steps_json"])
        ops = [f"{st['phase']}:{st['operation']}:{st['system_id']}:{st['resource_id']}:{st['evidence_id']}" for st in steps]
        print(f"{s['case_id']}: {s['deletion_status']} ({len(steps)} steps) -> {ops}")

if __name__ == "__main__":
    analyze()

