  --glass-border-hover: rgba(99, 102, 241, 0.35);
  --glass-glow: rgba(99, 102, 241, 0.15);

  /* Brand Accents */
  --accent-cyan: #06b6d4;
  --accent-cyan-glow: rgba(6, 182, 212, 0.25);
  --accent-indigo: #6366f1;
  --accent-indigo-glow: rgba(99, 102, 241, 0.25);
  --accent-purple: #8b5cf6;

  /* Status Colors */
  --status-complete: #10b981;
  --status-complete-bg: rgba(16, 185, 129, 0.12);
  --status-complete-border: rgba(16, 185, 129, 0.3);

  --status-incomplete: #f43f5e;
  --status-incomplete-bg: rgba(244, 63, 94, 0.12);
  --status-incomplete-border: rgba(244, 63, 94, 0.3);

  --status-na: #94a3b8;
  --status-na-bg: rgba(148, 163, 184, 0.12);
  --status-na-border: rgba(148, 163, 184, 0.3);

  --status-remediation: #f59e0b;
  --status-remediation-bg: rgba(245, 158, 11, 0.12);
  --status-remediation-border: rgba(245, 158, 11, 0.3);

  /* Typography */
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;
  --text-highlight: #38bdf8;

  /* Font Families */
  --font-heading: 'Outfit', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-ui: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* Transitions & Shadows */
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --shadow-card: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
