/**
 * GHOST DATA STILL EXISTS — FRONTEND CONTROLLER
 * Vanilla JavaScript UI Controller connecting to FastAPI Backend.
 */

const API_BASE = window.location.origin;

// State management
let state = {
  currentTab: 'tab-overview',
  datasetType: 'eval', // 'eval' or 'sample'
  statusFilter: 'ALL',
  searchQuery: '',
  currentPage: 1,
  pageSize: 20,
  totalPages: 1,
  currentCaseId: null,
  cachedEvidence: [],
  searchDebounceTimer: null
};

// Initialization on DOM loaded
document.addEventListener('DOMContentLoaded', () => {
  initDashboard();
});

async function initDashboard() {
  await loadStats();
  await loadCases();
  await loadEvidenceFiles();
  await loadBenchmark();
}

// -------------------------------------------------------------
// Toast Notifications
// -------------------------------------------------------------
function showToast(message, type = 'info') {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = 'toast';
  if (type === 'success') {
    toast.style.borderColor = 'var(--status-complete)';
  } else if (type === 'error') {
    toast.style.borderColor = 'var(--status-incomplete)';
  }

  toast.innerHTML = `
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
      ${type === 'success' 
        ? '<polyline points="20 6 9 17 4 12"></polyline>' 
        : '<circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line>'}
    </svg>
    <span>${message}</span>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    setTimeout(() => toast.remove(), 300);
  }, 4000);
}

// -------------------------------------------------------------
// Tab Switching
// -------------------------------------------------------------
function switchTab(tabId) {
  state.currentTab = tabId;
  document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.tab-pane').forEach(pane => pane.classList.remove('active'));

  const activeBtn = Array.from(document.querySelectorAll('.tab-btn')).find(b => b.getAttribute('onclick')?.includes(tabId));
  if (activeBtn) activeBtn.classList.add('active');

  const activePane = document.getElementById(tabId);
  if (activePane) activePane.classList.add('active');

  if (tabId === 'tab-cases') {
    loadCases();
  } else if (tabId === 'tab-benchmark') {
    loadBenchmark();
  }
}

// -------------------------------------------------------------
// Dashboard Overview & Stats
// -------------------------------------------------------------
async function loadStats() {
  try {
    const res = await fetch(`${API_BASE}/api/stats`);
    if (!res.ok) throw new Error("Failed to fetch stats");
    const data = await res.json();

    document.getElementById('kpi-eval-total').innerText = data.total_eval_cases || 518;
    document.getElementById('badge-cases-count').innerText = data.total_eval_cases || 518;
    document.getElementById('kpi-evidence-total').innerText = data.evidence_files_count || 94;
    document.getElementById('badge-evidence-count').innerText = `${data.evidence_files_count || 94} Files`;

    if (data.sample_evaluation) {
      document.getElementById('kpi-accuracy').innerText = `${data.sample_evaluation.status_accuracy}%`;
    }

    if (data.output_generated) {
      document.getElementById('kpi-output-status').innerText = 'Generated';
      document.getElementById('kpi-output-status').style.color = 'var(--status-complete)';
      const c = data.output_breakdown.COMPLETE || 0;
      const ic = data.output_breakdown.INCOMPLETE || 0;
      const na = data.output_breakdown.NOT_APPLICABLE || 0;
      document.getElementById('kpi-output-footer').innerHTML = 
        `<span class="highlight">${c} Complete</span>, ${ic} Incomplete, ${na} N/A`;
    }
  } catch (err) {
    console.error("Error loading stats:", err);
  }
}

// -------------------------------------------------------------
// Case Explorer
// -------------------------------------------------------------
function setDatasetType(type) {
  state.datasetType = type;
  state.currentPage = 1;
  document.getElementById('btn-dataset-eval').classList.toggle('active', type === 'eval');
  document.getElementById('btn-dataset-sample').classList.toggle('active', type === 'sample');
  loadCases();
}

function setStatusFilter(status) {
  state.statusFilter = status;
  state.currentPage = 1;
  const chips = document.querySelectorAll('.filter-group:last-child .filter-chip');
  chips.forEach(chip => {
    chip.classList.toggle('active', chip.innerText.toUpperCase() === status || (status === 'ALL' && chip.innerText === 'All'));
  });
  loadCases();
}

function handleSearch() {
  clearTimeout(state.searchDebounceTimer);
  state.searchDebounceTimer = setTimeout(() => {
    state.searchQuery = document.getElementById('case-search-input').value.trim();
    state.currentPage = 1;
    loadCases();
  }, 250);
}

function changePage(delta) {
  const newPage = state.currentPage + delta;
  if (newPage >= 1 && newPage <= state.totalPages) {
    state.currentPage = newPage;
    loadCases();
  }
}

async function loadCases() {
  const tbody = document.getElementById('cases-table-body');
  tbody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-dim);">Querying cases...</td></tr>`;

  try {
    const params = new URLSearchParams({
      dataset_type: state.datasetType,
      status: state.statusFilter,
      search: state.searchQuery,
      page: state.currentPage,
      page_size: state.pageSize
    });

    const res = await fetch(`${API_BASE}/api/cases?${params.toString()}`);
    if (!res.ok) throw new Error("Failed to load cases");
    const data = await res.json();

    state.totalPages = data.total_pages || 1;
    document.getElementById('pagination-info').innerText = 
      `Showing ${(data.page - 1) * data.page_size + 1} to ${Math.min(data.page * data.page_size, data.total_cases)} of ${data.total_cases} cases`;
    document.getElementById('current-page-num').innerText = data.page;
    document.getElementById('btn-prev-page').disabled = (data.page <= 1);
    document.getElementById('btn-next-page').disabled = (data.page >= state.totalPages);

    if (data.cases.length === 0) {
      tbody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-dim);">No cases match current filters</td></tr>`;
      return;
    }

    tbody.innerHTML = data.cases.map(c => {
      let badgeClass = 'badge-na';
      if (c.deletion_status === 'COMPLETE') badgeClass = 'badge-complete';
      else if (c.deletion_status === 'INCOMPLETE') badgeClass = 'badge-incomplete';

      return `
        <tr onclick="openCaseDossier('${c.case_id}')">
          <td class="mono-cell" style="font-weight: 700;">${c.case_id}</td>
          <td>${c.email}</td>
          <td class="mono-cell">${c.user_id}</td>
          <td><span style="font-size: 0.75rem; color: var(--text-dim);">${c.reported_status}</span></td>
          <td class="mono-cell" style="font-size: 0.72rem;">${c.audit_at ? c.audit_at.replace('T', ' ').replace('Z', '') : '--'}</td>
          <td><span class="badge ${badgeClass}">${c.deletion_status}</span></td>
          <td>
            <span style="font-size: 0.75rem; color: var(--text-muted);">
              ${c.findings_count} F / ${c.remediations_count} R / ${c.verifications_count} V (${c.steps_count} total)
            </span>
          </td>
          <td>
            <button class="btn btn-secondary btn-sm" onclick="event.stopPropagation(); openCaseDossier('${c.case_id}')">
              Inspect
            </button>
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    console.error("Error loading cases:", err);
    tbody.innerHTML = `<tr><td colspan="8" style="text-align: center; color: var(--status-incomplete);">Failed to load cases: ${err.message}</td></tr>`;
  }
}

// -------------------------------------------------------------
// Case Dossier Drawer
// -------------------------------------------------------------
async function openCaseDossier(caseId) {
  state.currentCaseId = caseId;
  const drawer = document.getElementById('case-drawer');
  const backdrop = document.getElementById('drawer-backdrop');
  drawer.classList.add('open');
  backdrop.classList.add('open');

  document.getElementById('dossier-case-id').innerText = caseId;
  document.getElementById('dossier-step-list').innerHTML = `<p style="color: var(--text-dim); font-size: 0.8rem;">Loading dossier intelligence...</p>`;

  try {
    const res = await fetch(`${API_BASE}/api/cases/${caseId}`);
    if (!res.ok) throw new Error("Failed to load case detail");
    const data = await res.json();
    renderDossier(data);
  } catch (err) {
    console.error("Error loading dossier:", err);
    document.getElementById('dossier-step-list').innerHTML = `<p style="color: var(--status-incomplete);">Failed to load case: ${err.message}</p>`;
  }
}

function closeDrawer() {
  document.getElementById('case-drawer').classList.remove('open');
  document.getElementById('drawer-backdrop').classList.remove('open');
  state.currentCaseId = null;
}

function renderDossier(data) {
  document.getElementById('dossier-case-id').innerText = data.case_id;
  document.getElementById('dossier-email').innerText = data.email;

  const stBadge = document.getElementById('dossier-status-badge');
  stBadge.innerText = data.deletion_status;
  stBadge.className = `badge badge-${data.deletion_status === 'COMPLETE' ? 'complete' : data.deletion_status === 'INCOMPLETE' ? 'incomplete' : 'na'}`;

  // Identity profile
  const profile = data.identity_profile || {};
  document.getElementById('dossier-user-id').innerText = profile.user_id || 'UNRESOLVED';
  document.getElementById('dossier-name').innerText = profile.name || '--';
  document.getElementById('dossier-current-email').innerText = profile.current_email || data.email;
  document.getElementById('dossier-phone').innerText = profile.phone || '--';
  document.getElementById('dossier-all-emails').innerText = (profile.all_emails || [data.email]).join(', ');
  document.getElementById('dossier-email-hash').innerText = profile.email_hash || '--';

  // Intent
  document.getElementById('dossier-request-text').innerText = `"${data.request_text || '(No request text provided)'}"`;
  const intentAuth = document.getElementById('dossier-intent-auth');
  const isAuth = data.intent_analysis?.is_authorized;
  intentAuth.innerText = isAuth ? 'AUTHORIZED (Deletion Request)' : 'NOT APPLICABLE (Non-Deletion / Other)';
  intentAuth.style.color = isAuth ? 'var(--status-complete)' : 'var(--status-na)';
  document.getElementById('dossier-intent-reason').innerText = data.intent_analysis?.reason || '--';

  // Timestamps
  document.getElementById('dossier-requested-at').innerText = data.requested_at || '--';
  document.getElementById('dossier-reported-claim').innerText = data.reported_status || '--';
  document.getElementById('dossier-reported-at').innerText = data.reported_at || '--';
  document.getElementById('dossier-audit-at').innerText = data.audit_at || '--';

  // Steps
  const steps = data.steps || [];
  document.getElementById('dossier-steps-count').innerText = `${steps.length} Steps`;
  document.getElementById('dossier-raw-json').innerText = JSON.stringify(steps, null, 2);

  const stepList = document.getElementById('dossier-step-list');
  if (steps.length === 0) {
    stepList.innerHTML = `<p style="font-size: 0.8rem; color: var(--text-dim); padding: 0.5rem 0;">No steps required (NOT_APPLICABLE or empty plan).</p>`;
    return;
  }

  stepList.innerHTML = steps.map(s => {
    let pClass = 'step-verification';
    let bClass = 'badge-verification';
    if (s.phase === 'FINDING') {
      pClass = 'step-finding';
      bClass = 'badge-finding';
    } else if (s.phase === 'REMEDIATION') {
      pClass = 'step-remediation';
      bClass = 'badge-remediation';
    }

    return `
      <div class="step-item ${pClass}">
        <div class="step-left">
          <div class="step-number">${s.step_no}</div>
          <div class="step-details">
            <h4>${s.system_id} // ${s.resource_id}</h4>
            <p>${s.operation} &rarr; Target State: <strong style="color: #fff;">${s.state}</strong></p>
          </div>
        </div>
        <div class="step-right">
          <span class="badge ${bClass}">${s.phase}</span>
          ${s.evidence_id ? `<span class="badge badge-na" style="cursor: pointer;" onclick="viewEvidenceInCatalog('${s.evidence_id}')">${s.evidence_id}</span>` : ''}
        </div>
      </div>
    `;
  }).join('');
}

async function reAuditCurrentCase() {
  if (!state.currentCaseId) return;
  showToast(`Re-auditing ${state.currentCaseId}...`, 'info');
  try {
    const res = await fetch(`${API_BASE}/api/audit/case/${state.currentCaseId}`, { method: 'POST' });
    if (!res.ok) throw new Error("Audit failed");
    const data = await res.json();
    showToast(`Case ${state.currentCaseId} audited: ${data.deletion_status}`, 'success');
    openCaseDossier(state.currentCaseId);
    loadCases();
  } catch (err) {
    showToast(`Audit error: ${err.message}`, 'error');
  }
}

// -------------------------------------------------------------
// Full Batch Audit & Generate output.csv
// -------------------------------------------------------------
async function runAllAudits() {
  const btn = document.getElementById('btn-run-all');
  btn.disabled = true;
  btn.innerText = 'Auditing 518 cases...';
  showToast("Running audit pipeline on all 518 evaluation requests...", "info");

  try {
    const res = await fetch(`${API_BASE}/api/audit/run-all`, { method: 'POST' });
    if (!res.ok) throw new Error("Full audit failed");
    const data = await res.json();

    showToast(`Audit completed! Generated root output.csv (${data.total_cases_audited} rows)`, "success");
    await loadStats();
    await loadCases();
  } catch (err) {
    console.error("Error running audits:", err);
    showToast(`Audit failed: ${err.message}`, "error");
  } finally {
    btn.disabled = false;
    btn.innerHTML = `
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
      Audit All 518 Cases
    `;
  }
}

// -------------------------------------------------------------
// Sample Benchmark & Accuracy Evaluation
// -------------------------------------------------------------
async function loadBenchmark() {
  try {
    const res = await fetch(`${API_BASE}/api/evaluate`);
    if (!res.ok) throw new Error("Failed to evaluate benchmark");
    const data = await res.json();

    document.getElementById('bench-status-acc').innerText = `${(data.status_accuracy * 100).toFixed(2)}%`;
    document.getElementById('bench-seq-acc').innerText = `${(data.sequence_accuracy * 100).toFixed(2)}%`;
    document.getElementById('bench-field-acc').innerText = `${(data.field_accuracy * 100).toFixed(2)}%`;
    document.getElementById('badge-benchmark-status').innerText = `${data.status_matches}/${data.total_cases} Matched`;

    const listContainer = document.getElementById('benchmark-cases-list');
    if (!data.mismatches || data.mismatches.length === 0) {
      listContainer.innerHTML = `<div class="dossier-card" style="text-align: center; color: var(--status-complete); font-weight: 600;">100% Exact Match on All 32 Sample Cases!</div>`;
      return;
    }

    listContainer.innerHTML = data.mismatches.map(m => {
      return `
        <div class="dossier-card" style="border-left: 4px solid ${m.pred_status === m.gt_status ? 'var(--status-complete)' : 'var(--status-incomplete)'}">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem;">
            <div style="font-family: var(--font-heading); font-weight: 700; font-size: 0.95rem;">
              ${m.case_id}
            </div>
            <div>
              Predicted: <span class="badge ${m.pred_status === 'COMPLETE' ? 'badge-complete' : 'badge-incomplete'}">${m.pred_status}</span>
              vs Ground Truth: <span class="badge ${m.gt_status === 'COMPLETE' ? 'badge-complete' : 'badge-incomplete'}">${m.gt_status}</span>
            </div>
          </div>
          <div style="font-size: 0.75rem; color: var(--text-dim); margin-bottom: 0.5rem;">
            Predicted Steps: ${m.pred_steps_count} | Ground Truth Steps: ${m.gt_steps_count}
          </div>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;">
            <div>
              <span style="font-size: 0.7rem; color: var(--text-muted); text-transform: uppercase;">Predicted Steps:</span>
              <pre class="code-block" style="font-size: 0.7rem; max-height: 140px;">${JSON.stringify(m.pred_steps, null, 2)}</pre>
            </div>
            <div>
              <span style="font-size: 0.7rem; color: var(--text-muted); text-transform: uppercase;">Ground Truth Steps:</span>
              <pre class="code-block" style="font-size: 0.7rem; max-height: 140px; color: #34d399;">${JSON.stringify(m.gt_steps, null, 2)}</pre>
            </div>
          </div>
        </div>
      `;
    }).join('');
  } catch (err) {
    console.error("Benchmark error:", err);
  }
}

async function runBenchmarkEvaluation() {
  showToast("Re-evaluating 32 sample cases...", "info");
  await loadBenchmark();
  showToast("Benchmark evaluation updated!", "success");
}

// -------------------------------------------------------------
// Evidence Catalog & Viewer
// -------------------------------------------------------------
async function loadEvidenceFiles() {
  try {
    const res = await fetch(`${API_BASE}/api/evidence`);
    if (!res.ok) throw new Error("Failed to load evidence files");
    const data = await res.json();
    state.cachedEvidence = data.files || [];

    const listEl = document.getElementById('evidence-files-list');
    listEl.innerHTML = state.cachedEvidence.map(f => {
      return `
        <div style="padding: 0.75rem 1rem; border-bottom: 1px solid var(--glass-border); cursor: pointer; transition: var(--transition-fast);" 
             onclick="selectEvidenceFile('${f.file_id}')"
             id="ev-item-${f.file_id}">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.2rem;">
            <span class="mono-cell" style="font-weight: 700;">${f.file_id}</span>
            <span class="badge badge-na" style="font-size: 0.65rem;">${f.category}</span>
          </div>
          <div style="font-size: 0.75rem; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
            ${f.file_path}
          </div>
          <div style="font-size: 0.68rem; color: var(--text-dim); margin-top: 0.2rem;">
            ${(f.size_bytes / 1024).toFixed(1)} KB • Captured: ${f.captured_at ? f.captured_at.replace('T', ' ').replace('Z', '') : '--'}
          </div>
        </div>
      `;
    }).join('');

    if (state.cachedEvidence.length > 0) {
      selectEvidenceFile(state.cachedEvidence[0].file_id);
    }
  } catch (err) {
    console.error("Error loading evidence:", err);
  }
}

async function selectEvidenceFile(fileId) {
  document.querySelectorAll('#evidence-files-list > div').forEach(el => el.style.background = 'transparent');
  const activeEl = document.getElementById(`ev-item-${fileId}`);
  if (activeEl) activeEl.style.background = 'var(--bg-surface-elevated)';

  const contentBox = document.getElementById('ev-viewer-content');
  contentBox.innerText = 'Loading artifact content...';

  try {
    const res = await fetch(`${API_BASE}/api/evidence/${fileId}`);
    if (!res.ok) throw new Error("Failed to read evidence artifact");
    const data = await res.json();

    document.getElementById('ev-viewer-title').innerText = `${data.file_id} — ${data.file_path}`;
    document.getElementById('ev-viewer-meta').innerText = 
      `Origin: ${data.origin} | Captured At: ${data.captured_at} | Size: ${(data.size_bytes / 1024).toFixed(1)} KB`;

    contentBox.innerText = data.content_preview || '(Empty file content)';
  } catch (err) {
    contentBox.innerText = `Error: ${err.message}`;
  }
}

function viewEvidenceInCatalog(fileId) {
  closeDrawer();
  switchTab('tab-evidence');
  setTimeout(() => selectEvidenceFile(fileId), 150);
}

function copyEvidenceContent() {
  const content = document.getElementById('ev-viewer-content').innerText;
  navigator.clipboard.writeText(content).then(() => {
    showToast("Evidence content copied to clipboard!", "success");
  });
}

// -------------------------------------------------------------
// Submission Packaging
// -------------------------------------------------------------
async function packageSubmission() {
  showToast("Packaging code.zip for submission...", "info");
  try {
    const res = await fetch(`${API_BASE}/api/package`, { method: 'POST' });
    if (!res.ok) throw new Error("Packaging failed");
    const data = await res.json();

    showToast(`code.zip generated successfully (${(data.size_bytes / 1024).toFixed(1)} KB)`, "success");
    switchTab('tab-submission');
  } catch (err) {
    showToast(`Packaging error: ${err.message}`, "error");
  }
}

