/* ==========================================================================
   ENTERPRISE ADMIN DASHBOARD DESIGN SYSTEM (Postman / Swiggy / Linear Theme)
   Layout: Hotstar/JioCinema Hover-Overlay Spring Sidebar (No content push)
   Animations: Framer-Motion style spring physics + Shimmer Skeleton Loaders
   Icons: Lucide SVG Outline Icons
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap');

:root {
  /* Surface Tokens (Postman / Linear Enterprise Dark) */
  --bg-canvas: #090d16;
  --bg-sidebar: #0e1424;
  --bg-surface: #131c31;
  --bg-surface-elevated: #1a2642;
  --bg-surface-hover: #223256;
  --bg-input: #0f172a;

  /* Borders & Dividers */
  --border-subtle: rgba(255, 255, 255, 0.07);
  --border-medium: rgba(255, 255, 255, 0.12);
  --border-focus: #f97316;

  /* Vibrant Accents (Postman Orange & Cyber Forensics) */
  --accent-orange: #f97316;
  --accent-orange-hover: #ea580c;
  --accent-orange-glow: rgba(249, 115, 22, 0.25);

  --accent-cyan: #06b6d4;
  --accent-cyan-glow: rgba(6, 182, 212, 0.25);
  --accent-indigo: #6366f1;
  --accent-purple: #a855f7;

  /* Semantic Feedback */
  --status-complete: #10b981;
  --status-complete-bg: rgba(16, 185, 129, 0.12);
  --status-complete-border: rgba(16, 185, 129, 0.3);

  --status-incomplete: #f43f5e;
  --status-incomplete-bg: rgba(244, 63, 94, 0.12);
  --status-incomplete-border: rgba(244, 63, 94, 0.3);

  --status-na: #94a3b8;
  --status-na-bg: rgba(148, 163, 184, 0.12);
  --status-na-border: rgba(148, 163, 184, 0.3);

  --status-remediation: #f59e0b;
  --status-remediation-bg: rgba(245, 158, 11, 0.12);

  /* Typography */
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-tertiary: #64748b;
  --text-white: #ffffff;

  /* Dimensions */
  --rail-width: 68px;
  --sidebar-expanded-width: 260px;
  --topbar-height: 64px;

  /* Fonts */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-display: 'Plus Jakarta Sans', var(--font-sans);
  --font-mono: 'JetBrains Mono', monospace;

  /* Framer-Motion Spring Easing Curves */
  --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Reset & Global */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background-color: var(--bg-canvas);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
