}

/* App Shell Grid Layout */
.app-shell {
  display: flex;
  min-height: 100vh;
  width: 100vw;
  position: relative;
}

/* ==========================================================================
   HOTSTAR / JIOCINEMA STYLE COLLAPSIBLE OVERLAY SIDEBAR
   Layout behavior: Fixed 68px rail anchor so right dashboard NEVER shifts.
   Inner sidebar overlays smoothly to 260px on hover.
   ========================================================================== */
.sidebar-layout-anchor {
