/* Main Dashboard Body Container */
.dashboard-viewport {
  padding: 1.75rem;
  flex: 1;
  max-width: 1680px;
  margin: 0 auto;
  width: 100%;
}

/* ==========================================================================
   SHIMMER SKELETON LOADING ANIMATION SYSTEM
   Continuous sweep animation when loading or backend disconnected
   ========================================================================== */
@keyframes skeleton-shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.skeleton-shimmer {
  background: linear-gradient(90deg, #131c31 25%, #223256 37%, #131c31 63%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.5s infinite ease-in-out;
  border-radius: 6px;
  position: relative;
  overflow: hidden;
}

.skeleton-kpi-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
