.kpi-meta {
  font-size: 0.75rem;
  color: var(--text-tertiary);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.kpi-meta .highlight {
  color: var(--status-complete);
  font-weight: 600;
}

/* Card Panel Container */
.content-panel {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  padding: 1.5rem;
