368:   const intentAuth = document.getElementById('drawer-intent-auth');
369:   const isAuth = data.intent_analysis?.is_authorized;
370:   intentAuth.innerText = isAuth ? 'AUTHORIZED (Deletion Request)' : 'NOT APPLICABLE (Access/Export/Correction)';
371:   intentAuth.style.color = isAuth ? 'var(--status-complete)' : 'var(--status-na)';
