377:   document.getElementById('drawer-reported-at').innerText = data.reported_at || '--';
378:   document.getElementById('drawer-audit-at').innerText = data.audit_at || '--';
379: 
380:   // Steps
381:   const steps = data.steps || [];
382:   document.getElementById('drawer-steps-badge').innerText = `${steps.length} Steps`;
383:   document.getElementById('drawer-raw-json').innerText = JSON.stringify(steps, null, 2);
384: 
385:   const container = document.getElementById('drawer-steps-list');
386:   if (steps.length === 0) {
387:     container.innerHTML = `<p style="font-size: 0.8rem; color: var(--text-tertiary); padding: 0.5rem 0;">No steps (NOT_APPLICABLE or empty plan).</p>`;
